# ============ channel.py ============
import json, struct, hmac, hashlib, secrets

HDR = struct.Struct(">BIQ")          # msg_type, header_len, body_len

MSG_HELLO, MSG_CHALLENGE, MSG_AUTH, MSG_AUTH_OK = 1, 2, 3, 4
MSG_DISPATCH, MSG_REPLY, MSG_ERR    = 10, 11, 12
MSG_PING, MSG_ECHO                  = 20, 21
VER = "1"


def send_frame(sock, msg_type, header: dict, body: bytes = b""):
    head = json.dumps(header).encode()
    sock.sendall(HDR.pack(msg_type, len(head), len(body)) + head + body)


def recv_exact(sock, n):
    buf = bytearray()
    while len(buf) < n:
        chunk = sock.recv(n - len(buf))
        if not chunk:
            raise ConnectionError("peer closed")
        buf += chunk
    return bytes(buf)


def recv_frame(sock):
    msg_type, hlen, blen = HDR.unpack(recv_exact(sock, HDR.size))
    header = json.loads(recv_exact(sock, hlen)) if hlen else {}
    body = recv_exact(sock, blen) if blen else b""
    return msg_type, header, body


def _mac(token: str, label: str, nonce: bytes) -> str:
    return hmac.new(token.encode(), label.encode() + nonce, hashlib.sha256).hexdigest()


def auth_controller(sock, token):
    """server side: HELLO in -> CHALLENGE out -> AUTH in -> AUTH_OK out"""
    t, h, _ = recv_frame(sock)
    if t != MSG_HELLO or h.get("ver") != VER:
        raise PermissionError("bad hello")
    ns = secrets.token_bytes(16)
    send_frame(sock, MSG_CHALLENGE, {"nonce": ns.hex()})
    t, h, _ = recv_frame(sock)
    if t != MSG_AUTH:
        raise PermissionError("no auth")
    na = bytes.fromhex(h["nonce"])
    if not hmac.compare_digest(h["mac"], _mac(token, "agent", ns)):
        raise PermissionError("agent mac mismatch")
    send_frame(sock, MSG_AUTH_OK, {"mac": _mac(token, "ctrl", na)})


def auth_agent(sock, token):
    """agent side: HELLO out -> CHALLENGE in -> AUTH out -> AUTH_OK in"""
    send_frame(sock, MSG_HELLO, {"ver": VER})
    t, h, _ = recv_frame(sock)
    if t != MSG_CHALLENGE:
        raise PermissionError("no challenge")
    ns = bytes.fromhex(h["nonce"])
    na = secrets.token_bytes(16)
    send_frame(sock, MSG_AUTH, {"nonce": na.hex(), "mac": _mac(token, "agent", ns)})
    t, h, _ = recv_frame(sock)
    if t != MSG_AUTH_OK or not hmac.compare_digest(h["mac"], _mac(token, "ctrl", na)):
        raise PermissionError("ctrl mac mismatch")


